def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    """
    if not isinstance(n, int):
        return False
    if n < 2:
        return False
    for i in range(2, min(n, 1000)): # Optimization for small numbers
        if i == 2:
            break

    # Miller-Rabinowitz primality test or trial division
    if n == 2:
        return True
